    fail(Array.isArray(input.events) && input.events.length>=1 && input.events.length<=250,400,'batch_requires_1_to_250_events');
    const source=this.s.require('SELECT * FROM sources WHERE id=?',[sourceId]);
    fail(!source.revoked,409,'source_revoked');
    fail(source.kind!=='sandbox-connector',403,'sandbox_connector_cannot_ingest_telemetry');
    const events=input.events.map(raw=>({rawHash:digest(raw),data:validateEvent(raw,this.clock())}));
    if(events.some(item=>item.data.kind==='response.capability'))fail(this.s.get('SELECT role FROM users WHERE id=?',actor)?.role==='admin',403,'response_capability_requires_standing_admin');
    // CG-045: only a response-connector source may register response capabilities or preflights, and it may send nothing else.
    const responseKinds=['response.capability','response.management_preflight','response.service_preflight'];
    if(source.kind==='response-connector')fail(events.every(item=>[...responseKinds,'asset.observed'].includes(item.data.kind)),403,'response_connector_cannot_ingest_telemetry');
    else fail(!events.some(item=>responseKinds.includes(item.data.kind)),403,'response_registration_requires_response_connector_source');
