    if (e.kind==='log.batch'&&e.details.format==='gcp-audit-json') for(const r of e.details.records.filter(r=>r.outcome==='success'&&riskyGcpMethods.includes(r.signature)).slice(0,50))this.alert({key:`CG-CLOUD-AUDIT-048:${e.details.batch_id}:${r.line}`,assetId:e.asset_id,sourceId:e.source_id,rule:'CG-CLOUD-AUDIT-048',severity:/Sink|CreateServiceAccountKey|SetIamPolicy|SetIAMPolicy|securityPolicies.delete/.test(r.signature)?'high':'medium',title:`Sensitive Google Cloud call / استدعاء Google Cloud حساس: ${r.signature} by ${r.user||'unknown'} (${r.host||''})`.slice(0,300),eventId:e.id});
    if (e.kind==='log.batch'&&e.details.format==='aws-cloudtrail-json') {const fails={};for(const r of e.details.records.filter(r=>r.action==='ConsoleLogin'&&r.outcome==='failure'))fails[r.user||r.src_ip||'unknown']=(fails[r.user||r.src_ip||'unknown']||0)+1;for(const [who,n] of Object.entries(fails).filter(([,n])=>n>=5))this.alert({key:`CG-CLOUD-TRAIL-046:${e.details.batch_id}:login:${who}`,assetId:e.asset_id,sourceId:e.source_id,rule:'CG-CLOUD-TRAIL-046',severity:'medium',title:`Repeated AWS console sign-in failures / فشل متكرر لدخول AWS: ${who} (${n})`.slice(0,300),eventId:e.id});}
