    if (e.kind==='container.image_scan'&&e.details.fixable_critical.length) this.alert({key:`CG-CONTAINER-VULN-105:${e.details.image}:${e.details.fixable_critical.map(v=>v.id).sort().join(',').slice(0,200)}`,assetId:e.asset_id,sourceId:e.source_id,rule:'CG-CONTAINER-VULN-105',severity:'high',title:`Image ${e.details.image} has ${e.details.fixable_critical.length} critical vulnerabilities with fixes available / الصورة ${e.details.image} فيها ثغرات حرجة لها إصلاحات`,eventId:e.id});
    if (e.kind==='remote.authenticated') for(const v of this.managementViolations(e)) this.alert({key:`CG-MGMT-ACCESS-102:${e.id}:${v.id}`,assetId:e.asset_id,sourceId:e.source_id,rule:'CG-MGMT-ACCESS-102',severity:v.severity,title:`${v.title} / ${v.title_ar}`,eventId:e.id});
