    const catalog=detectionCatalog(),catalogIds=new Set(catalog.map(r=>r.id)),kindsSeen=new Set(this.s.all('SELECT DISTINCT kind FROM events WHERE received_at>=?',since).map(r=>r.kind));
    const by_rule=[...new Set([...catalog.map(r=>r.id),...rules.keys()])].map(id=>{const r=rules.get(id)||{alerts:0,tp:0,benign:0,fp:0,open:0,detect:[],respond:[]},correct=r.tp+r.benign,judged=correct+r.fp,rule=catalog.find(x=>x.id===id);
      const precision=ratio(correct,judged);return {rule_id:id,catalog:catalogIds.has(id),evidence_kind:rule?.evidence_kind||null,evidence_received:rule?kindsSeen.has(rule.evidence_kind):null,alerts:r.alerts,true_positive:r.tp,benign_true_positive:r.benign,false_positive:r.fp,not_triaged:r.open,precision,false_positive_rate:ratio(r.fp,judged),mean_detect_minutes:mean(r.detect),mean_respond_minutes:mean(r.respond),
        state:!r.alerts?(rule&&!kindsSeen.has(rule.evidence_kind)?'no-evidence-received':'no-hits-in-window'):!judged?'not-triaged':precision<0.5?'noisy':'measured'};})
      .sort((a,b)=>b.alerts-a.alerts||a.rule_id.localeCompare(b.rule_id));
    const tp=by_rule.reduce((n,r)=>n+r.true_positive,0),benign=by_rule.reduce((n,r)=>n+r.benign_true_positive,0),fp=by_rule.reduce((n,r)=>n+r.false_positive,0),notTriaged=by_rule.reduce((n,r)=>n+r.not_triaged,0);
    const sources=this.sources(),health=new Map(sources.map(s=>[s.id,s.health])),assets=this.s.all('SELECT id,source_id FROM assets'),withEvidence=new Set(this.s.all('SELECT DISTINCT asset_id FROM events WHERE asset_id IS NOT NULL AND received_at>=?',since).map(r=>r.asset_id));
    const by_health={};for(const a of assets){const h=health.get(a.source_id)||'unknown';by_health[h]=(by_health[h]||0)+1;}
    const receiving=assets.filter(a=>health.get(a.source_id)==='receiving').length,evidenced=assets.filter(a=>withEvidence.has(a.id)).length;
    const catalogRules=catalog.length,evaluable=catalog.filter(r=>kindsSeen.has(r.evidence_kind)).length,fired=by_rule.filter(r=>r.catalog&&r.alerts).length,measured=by_rule.filter(r=>r.catalog&&r.true_positive+r.benign_true_positive+r.false_positive).length;
    const jobs=this.s.all('SELECT connector_id,phase,status,queued_at,completed_at,completion_json FROM response_jobs WHERE queued_at>=?',since).map(j=>({...j,status:j.status==='failed'&&/"outcome":"expired"/.test(j.completion_json||'')?'expired':j.status})),connectors=new Map();
    for(const j of jobs){const c=connectors.get(j.connector_id)||{connector_id:j.connector_id,queued:0,succeeded:0,failed:0,pending:0,rollback_jobs:0,durations:[]};c.queued++;if(j.phase==='rollback')c.rollback_jobs++;if(j.status==='succeeded'){c.succeeded++;if(j.completed_at)c.durations.push(minutes(j.queued_at,j.completed_at));}else if(j.status==='failed')c.failed++;else if(j.status==='expired')c.expired=(c.expired||0)+1;else c.pending++;connectors.set(j.connector_id,c);}
    const actionRows=this.s.all('SELECT type,status FROM actions WHERE requested_at>=?',since),action_status={};for(const a of actionRows)action_status[a.status]=(action_status[a.status]||0)+1;
    const failedActions=actionRows.filter(a=>a.status==='failed').length,completedActions=actionRows.filter(a=>['verified','rolled-back','failed'].includes(a.status)).length,failedByType={};for(const a of actionRows.filter(a=>a.status==='failed'))failedByType[a.type]=(failedByType[a.type]||0)+1;
