      detection_quality:{alerts:alerts.length,dispositioned:tp+benign+fp,true_positive:tp,benign_true_positive:benign,false_positive:fp,not_triaged:notTriaged,precision:ratio(tp+benign,tp+benign+fp),false_positive_rate:ratio(fp,tp+benign+fp),triage_completion:ratio(tp+benign+fp,alerts.length)},
