    all.sort((a,b)=>b.time.localeCompare(a.time));const query=q.toLowerCase(),matching=all.filter(r=>(!category||r.category===category)&&(!query||[r.src_ip,r.dst_ip,r.user,r.host,r.mac,r.query,r.signature,r.message,r.action].filter(Boolean).join(' ').toLowerCase().includes(query)));
