      return {schema_version:'cg.investigation/1',generated_at:this.now(),method:'deterministic-evidence-report; no language model',asset_id:a.id,hostname:a.hostname,conclusions:[{claim:'Asset observed by configured source',claim_ar:'أصل رصده مصدر مهيأ',evidence:a.events.map(e=>e.id)},{claim:`Telemetry: ${a.visibility}`,source_id:a.source_id},{claim:'Prevention has not been independently tested',claim_ar:'لم يُختبر المنع اختبارًا مستقلًا',evidence:[]}],source:a.source,protection:a.protection,alerts:a.alerts,events:a.events,limitations:['Imported source reports are not independently authenticated endpoint facts.','No attribution of a person from IP, relay or shared account.','No commands or model requests are executed.']};
