    this.s.run('INSERT INTO source_delivery(source_id,queue_depth,oldest_queued_at,delivery_attempt,reported_at,max_delay_minutes) VALUES (?,?,?,?,?,?) ON CONFLICT(source_id) DO UPDATE SET queue_depth=excluded.queue_depth,oldest_queued_at=excluded.oldest_queued_at,delivery_attempt=excluded.delivery_attempt,reported_at=excluded.reported_at,max_delay_minutes=MAX(source_delivery.max_delay_minutes,excluded.max_delay_minutes)',sourceId,queue_depth,oldest_queued_at,delivery_attempt,this.now(),Math.round(delay*10)/10);
